// Import user-reviewed history into an OFFLINE SQLite snapshot. No network calls,
// messages, applications, task claims, or credentials are generated by this tool.
import { readFileSync } from 'node:fs';
import { DatabaseSync } from 'node:sqlite';
import { createRequire } from 'node:module';
import { pathToFileURL } from 'node:url';
const require = createRequire(import.meta.url);
const addNote = (old, text) => old?.includes(text) ? old : [old, text].filter(Boolean).join('\n\n');
export function mergeHistory(original, manifest, now) {
  const workspace = structuredClone(original), events = [], archives = [], audit = [];
  for (const item of manifest.jobs) {
    const incoming = item.job;
    let job = workspace.jobs.find(j => j.id === (item.existingId || incoming.id));
    if (item.existingId && !job) throw Error(`Reviewed job alias missing: ${item.existingId}`);
    if (!job && item.archive) { archives.push(incoming); continue; }
    if (!job) { job = structuredClone(incoming); workspace.jobs.push(job); }
    else {
      // Keep stronger live source URLs, ownership, user edits and existing IDs.
      job.sourceEvidence = addNote(job.sourceEvidence, incoming.sourceEvidence);
      if (item.archive) job.gap = addNote(job.gap, 'Imported history reports this role closed; reconcile against existing evidence before any application.');
    }
    if (item.application) {
      const prior = workspace.applications.find(a => a.jobId === job.id);
      if (!prior) workspace.applications.push({jobId:job.id, updatedAt:now, origin:'Agent', ...item.application});
      else { prior.notes = addNote(prior.notes, item.application.notes); }
    }
    audit.push({sourceId:incoming.id, canonicalId:job.id});
  }
  for (const item of manifest.contacts) {
    const incoming = item.contact;
    const byId = item.existingId && workspace.contacts.find(c => c.id === item.existingId);
    const byLinkedin = workspace.contacts.filter(c => c.linkedin && c.linkedin.replace(/\/$/, '').toLowerCase() === incoming.linkedin.toLowerCase());
    if (byLinkedin.length > 1 || (byId && byLinkedin.some(c => c.id !== byId.id))) throw Error('Conflicting contact identity; manual reconciliation required.');
    if (item.existingId && !byId) throw Error(`Reviewed contact alias missing: ${item.existingId}`);
    let contact = byId || byLinkedin[0] || workspace.contacts.find(c => c.id === incoming.id);
    if (!contact) {contact = structuredClone(incoming); workspace.contacts.push(contact);}
    else {
      if (contact.email && contact.email !== incoming.email) throw Error('Imported email conflicts with existing contact.');
      if (contact.linkedin && contact.linkedin.replace(/\/$/, '').toLowerCase() !== incoming.linkedin.toLowerCase()) throw Error('Imported LinkedIn identity conflicts with existing contact.');
      contact.linkedin ||= incoming.linkedin;
      contact.email ||= incoming.email;
      contact.emailSource ||= incoming.emailSource;
      contact.evidence = addNote(contact.evidence, incoming.evidence);
      // Bounce is address-specific. LinkedIn replies must not mark email replied.
      if (item.bounced) contact.emailStatus = 'Stopped';
      else if (!['Replied','Stopped'].includes(contact.emailStatus)) contact.emailStatus = incoming.emailStatus;
    }
    const base = `${manifest.importId}:${incoming.id}`;
    const emit = (kind, text) => events.push({id:`${base}:${kind}`,actor:'user',kind,contactId:contact.id,at:now,email:incoming.email,text:`Historical report supplied by user; event date 2026-11-04 unless noted. ${text} Not independently verified by Gmail. No message is sent by this import.`});
    emit('sent_reported','Initial outreach email reported sent.');
    emit('linkedin_sent_reported','LinkedIn InMail reported sent; connection acceptance is not established.');
    if (item.bounced) emit('invalid_address_reported','Initial inferred email address reported nonexistent/bounced. Do not resend or try alternate addresses automatically.');
    if (item.replyChannel) emit(item.replyChannel === 'email' ? 'reply_reported' : 'linkedin_reply_reported',item.note);
    audit.push({sourceId:incoming.id,canonicalId:contact.id});
  }
  return {workspace,events,archives,audit};
}
export function applyHistory(dbPath, manifestPath) {
  const {isWorkspace} = require('../.test-build/logic.js');
  const d = new DatabaseSync(dbPath), manifest = JSON.parse(readFileSync(manifestPath,'utf8'));
  d.exec('PRAGMA busy_timeout=5000; BEGIN IMMEDIATE');
  try {
    const row = d.prepare('SELECT body,revision FROM workspace WHERE id=1').get();
    const result = mergeHistory(JSON.parse(row.body),manifest,new Date().toISOString());
    if (!isWorkspace(result.workspace)) throw Error('Imported workspace failed validation.');
    const changed = d.prepare('UPDATE workspace SET body=?, revision=revision+1 WHERE id=1 AND revision=?').run(JSON.stringify(result.workspace),row.revision);
    if (changed.changes !== 1) throw Error('Workspace changed during import.');
    for (const e of result.events) d.prepare('INSERT OR IGNORE INTO portal_events(id,body) VALUES (?,?)').run(e.id,JSON.stringify(e));
    for (const j of result.archives) d.prepare('INSERT OR IGNORE INTO archived_jobs(id,body,archived_at,reason) VALUES (?,?,?,?)').run(j.id,JSON.stringify(j),new Date().toISOString(),'User-supplied history: closed, filtered or unresolved identity. Not a new active opportunity.');
    // Historical submitted applications must never be submitted again via an old queue.
    const submitted = new Set(result.workspace.applications.filter(a => !['Saved','To apply'].includes(a.stage)).map(a => a.jobId));
    let heldTasks=0;
    for (const row of d.prepare('SELECT id,body FROM execution_tasks').all()) {
      const t=JSON.parse(row.body),jobId=t.entityId || t.input?.job?.id;
      if (submitted.has(jobId) && ['application_prepare','application_submit'].includes(t.kind) && ['queued','claimed','review','blocked'].includes(t.status) && !t.result?.summary?.startsWith('Historical import reports')) {
        t.status='blocked';t.version+=1;t.updatedAt=new Date().toISOString();
        t.blocker='Historical import reports this application already submitted. Check employer/Gmail evidence before any retry; do not submit again.';
        t.result={...t.result,summary:t.blocker};
        delete t.claimToken;
        d.prepare('UPDATE execution_tasks SET body=? WHERE id=?').run(JSON.stringify(t),row.id);heldTasks++;
      }
    }
    d.prepare('INSERT INTO settings(key,body) VALUES (?,?) ON CONFLICT(key) DO UPDATE SET body=excluded.body').run(`history_import:${manifest.importId}`,JSON.stringify({at:new Date().toISOString(),sourceSha256:manifest.sourceSha256,audit:result.audit,sourceRows:manifest.sourceRows}));
    d.exec('COMMIT');
    return {jobs:result.workspace.jobs.length,contacts:result.workspace.contacts.length,applications:result.workspace.applications.length,reportedEvents:result.events.length,archivedReports:result.archives.length,heldTasks,integrity:d.prepare('PRAGMA integrity_check').get().integrity_check};
  } catch(e) {d.exec('ROLLBACK');throw e;} finally {d.close();}
}
if (process.argv[1] && import.meta.url===pathToFileURL(process.argv[1]).href) {
  if (process.argv.length!==4) throw Error('Usage: node scripts/import-history.mjs OFFLINE_SNAPSHOT MANIFEST');
  console.log(JSON.stringify(applyHistory(process.argv[2],process.argv[3])));
}
